def decode(buf):
    """Decode a percent-encoded byte string back to the original bytes.

    Partial percent sequences at either end (caused by truncation) are dropped.
    """
    out = bytearray()
    i = 0
    n = len(buf)
    while i < n:
        if buf[i] == ord('%'):
            if i + 3 > n:
                # Truncated escape at the end: drop it.
                break
            try:
                out.append(int(buf[i+1:i+3], 16))
            except ValueError:
                # Not a valid escape; keep the '%' literally.
                out.append(buf[i])
                i += 1
                continue
            i += 3
        else:
            out.append(buf[i])
            i += 1
    return bytes(out)

