    """Encode an integer using MessagePack format.

    Positive integers use fixint (0-127), uint8 (0xcc), uint16 (0xcd),
    uint32 (0xce), or uint64 (0xcf) formats.
    Negative integers use negative fixint (-32 to -1), int8 (0xd0),
    int16 (0xd1), int32 (0xd2), or int64 (0xd3) formats.
    """
    if 0 <= x <= 0x7f:
        self.buf.append(x)
    elif -32 <= x < 0:
        self.buf.append(0xe0 | (x + 32))
    elif 0 <= x <= 0xff:
        self.buf.append(0xcc)
        self.buf += struct.pack('>B', x)
    elif 0 <= x <= 0xffff:
        self.buf.append(0xcd)
        self.buf += struct.pack('>H', x)
    elif 0 <= x <= 0xffffffff:
        self.buf.append(0xce)
        self.buf += struct.pack('>I', x)
    elif 0 <= x <= 0xffffffffffffffff:
        self.buf.append(0xcf)
        self.buf += struct.pack('>Q', x)
    elif -128 <= x < -32:
        self.buf.append(0xd0)
        self.buf += struct.pack('>b', x)
    elif -32768 <= x < -128:
        self.buf.append(0xd1)
        self.buf += struct.pack('>h', x)
